const raw = items[0].json || {};
const payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const alerts = Array.isArray(payload.alerts) && payload.alerts.length ? payload.alerts : [payload];
const staticData = $getWorkflowStaticData('global');
staticData.seenAlerts = staticData.seenAlerts || {};
const TTL = 6 * 60 * 60 * 1000;
const now = Date.now();

for (const [key, ts] of Object.entries(staticData.seenAlerts)) {
  if (!ts || now - ts > TTL) delete staticData.seenAlerts[key];
}

const severityMap = {
  critical: { priority: 50, severity: 70 },
  high: { priority: 50, severity: 70 },
  warning: { priority: 40, severity: 60 },
  medium: { priority: 40, severity: 60 },
  info: { priority: 30, severity: 50 },
  low: { priority: 20, severity: 50 },
};

const batchSeen = new Set();
const output = [];

for (const alert of alerts) {
  const labelsObj = alert.labels && !Array.isArray(alert.labels) ? alert.labels : {};
  const alertName = labelsObj.alertname || payload.title || alert.alertName || alert.title || alert.fingerprint || 'Alerta sin nombre';
  const instancia = labelsObj.instance || alert.instance || (payload.commonLabels && payload.commonLabels.instance) || payload.instance || 'desconocida';
  const estado = alert.status || payload.status || alert.state || payload.state || 'active';
  const fingerprint = alert.fingerprint || payload.fingerprint || (alertName + '|' + instancia);

  if (String(estado).toLowerCase() === 'resolved') {
    delete staticData.seenAlerts[fingerprint];
    continue;
  }

  if (batchSeen.has(fingerprint)) continue;
  batchSeen.add(fingerprint);

  const seenAt = staticData.seenAlerts[fingerprint];
  if (seenAt && now - seenAt < TTL) continue;

  const labels = Object.keys(labelsObj).length
    ? Object.entries(labelsObj).map(([k, v]) => k + '=' + v).join(', ')
    : (Array.isArray(alert.labels) ? alert.labels.map(l => (typeof l === 'string' ? l : (l.name || l))).join(', ') : '');

  let detalle = payload.message || (alert.annotations && (alert.annotations.description || alert.annotations.summary)) || 'Sin detalles adicionales';
  if (typeof detalle === 'string' && detalle.includes('\n')) {
    detalle = detalle.split('\n')[0];
  }

  const severityRaw = String(labelsObj.severity || alert.severity || payload.severity || '').toLowerCase();
  const sev = severityMap[severityRaw] || { priority: 30, severity: 50 };

  const description = [
    'Alerta de infraestructura detectada por Grafana.',
    'Alerta: ' + alertName,
    'Instancia: ' + instancia,
    'Estado: ' + estado,
    'Labels: ' + labels,
    'Detalle: ' + detalle,
    'Fingerprint: ' + fingerprint
  ].join('\n');

  const summary = 'Alerta infraestructura: ' + alertName;
  output.push({
    json: Object.assign({}, payload, {
      alertName,
      summary,
      description,
      fingerprint,
      priorityId: sev.priority,
      severityId: sev.severity
    })
  });
}

return output;

const staticData = $getWorkflowStaticData('global');
staticData.seenAlerts = staticData.seenAlerts || {};
const sourceItems = $('Enriquecer Alerta').all();
return items.map((item, index) => {
  const src = sourceItems[index]?.json || {};
  if (src.fingerprint) {
    staticData.seenAlerts[src.fingerprint] = Date.now();
  }
  return item;
});

const entries = Array.isArray(items) ? items : [items];
for (const item of entries) {
  const data = item.json || {};
  const err = data.error || data;
  const nodeName = (data.node && data.node.name) || data.nodeName || data.node || 'desconocido';
  console.error(JSON.stringify({
    ts: new Date().toISOString(),
    source: 'n8n-fl1-error-node',
    workflow: $workflow.name,
    executionId: $execution.id,
    node: typeof nodeName === 'string' ? nodeName : JSON.stringify(nodeName),
    message: err.message || String(err),
    description: err.description || null,
    stack: err.stack || null,
    fingerprint: data.fingerprint || null
  }, null, 2));
}
return [];

